import { app, BrowserWindow, type WebContents } from 'electron'
import { spawn } from 'node:child_process'
import { createHash } from 'node:crypto'
import { createWriteStream } from 'node:fs'
import fs from 'node:fs/promises'
import os from 'node:os'
import path from 'node:path'
import { Readable } from 'node:stream'
import type { UpdateInfo, UpdateManifest } from '../shared/types'

// Lightweight self-update: each GitHub release ships a `last.json` manifest
// (generated by tools/gen-last-json.mjs). We compare versions, download the
// installer for the current platform, verify sha512, then relaunch it.

const REPO = 'integemjack/github-manager'
// Releases are tagged v* and always stable; `releases/latest` resolves to the
// newest one, which ships last.json alongside the installers.
const MANIFEST_URL = `https://github.com/${REPO}/releases/latest/download/last.json`
const UA = 'github-manager-updater'

function platformKey(): string {
  const osName = process.platform === 'win32' ? 'win' : process.platform === 'darwin' ? 'mac' : 'linux'
  return `${osName}-${process.arch}`
}

function parseVersion(v: string): number[] {
  return v
    .replace(/^[vV]/, '')
    .split('.')
    .map((s) => parseInt(s, 10) || 0)
}

function versionGt(a: string, b: string): boolean {
  const pa = parseVersion(a)
  const pb = parseVersion(b)
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const d = (pa[i] ?? 0) - (pb[i] ?? 0)
    if (d !== 0) return d > 0
  }
  return false
}

async function fetchManifest(url: string): Promise<UpdateManifest | null> {
  try {
    const res = await fetch(url, { headers: { 'User-Agent': UA }, redirect: 'follow' })
    if (!res.ok) return null
    const data = (await res.json()) as UpdateManifest
    if (!data?.version || !data?.platforms) return null
    return data
  } catch {
    return null
  }
}

let downloadedFile: string | null = null
let downloading = false

export async function checkForUpdates(): Promise<UpdateInfo | null> {
  const current = app.getVersion()
  const manifest = await fetchManifest(MANIFEST_URL)
  if (!manifest) return null
  if (!versionGt(manifest.version, current)) return null

  const asset = manifest.platforms[platformKey()]
  if (!asset) return null

  return {
    current,
    latest: manifest.version,
    channel: manifest.channel === 'rolling' ? 'rolling' : 'stable',
    notes: manifest.notes ?? '',
    releaseUrl: manifest.releaseUrl ?? `https://github.com/${REPO}/releases`,
    downloadUrl: asset.url,
    sha512: asset.sha512,
    size: asset.size,
    fileName: asset.url.split('/').pop() ?? 'installer'
  }
}

function send(sender: WebContents | null | undefined, channel: string, payload: unknown): void {
  const w = sender
    ? BrowserWindow.fromWebContents(sender)
    : BrowserWindow.getAllWindows().find((x) => !x.isDestroyed()) ?? null
  w?.webContents.send(channel, payload)
}

export async function downloadUpdate(sender?: WebContents | null): Promise<void> {
  if (downloading) return
  const info = await checkForUpdates()
  if (!info) {
    send(sender, 'update:error', { message: '未发现可用的新版本' })
    return
  }
  downloading = true
  const dest = path.join(os.tmpdir(), `gm-update-${info.latest}-${info.fileName}`)
  try {
    // Reuse an already-verified download when possible
    try {
      const buf = await fs.readFile(dest)
      if (createHash('sha512').update(buf).digest('hex') === info.sha512) {
        downloadedFile = dest
        send(sender, 'update:downloaded', { path: dest })
        return
      }
    } catch {
      /* not downloaded yet */
    }

    const res = await fetch(info.downloadUrl, { headers: { 'User-Agent': UA }, redirect: 'follow' })
    if (!res.ok || !res.body) throw new Error(`下载失败 (HTTP ${res.status})`)

    const total = parseInt(res.headers.get('content-length') ?? '', 10) || info.size || 0
    const hash = createHash('sha512')
    const out = createWriteStream(dest)
    let received = 0
    let lastPercent = -1
    for await (const chunk of Readable.fromWeb(res.body as any)) {
      hash.update(chunk as Buffer)
      out.write(chunk as Buffer)
      received += (chunk as Buffer).length
      if (total > 0) {
        const percent = Math.min(99, Math.floor((received / total) * 100))
        if (percent !== lastPercent) {
          lastPercent = percent
          send(sender, 'update:progress', { percent })
        }
      }
    }
    await new Promise<void>((resolve, reject) => {
      out.end((err?: Error | null) => (err ? reject(err) : resolve()))
    })
    if (info.sha512 && hash.digest('hex') !== info.sha512.toLowerCase()) {
      await fs.rm(dest, { force: true })
      throw new Error('安装包校验失败（sha512 不匹配）')
    }
    downloadedFile = dest
    send(sender, 'update:downloaded', { path: dest })
  } catch (err: any) {
    send(sender, 'update:error', { message: err?.message ?? String(err) })
  } finally {
    downloading = false
  }
}

export function installUpdate(): void {
  if (process.platform !== 'win32' || !downloadedFile) return
  // NSIS installer takes over; quit shortly after launching it
  const child = spawn(downloadedFile, [], { detached: true, stdio: 'ignore' })
  child.unref()
  setTimeout(() => app.quit(), 200)
}

export function startAutoUpdateCheck(): void {
  // Only auto-check in packaged builds; dev can still check manually
  if (process.env.ELECTRON_RENDERER_URL) return
  // Each version is handled at most once per session: the auto-download
  // starts once, and re-checks won't re-raise a banner the user dismissed.
  const handled = new Set<string>()
  const check = () => {
    void (async () => {
      const info = await checkForUpdates()
      if (!info || handled.has(info.latest)) return
      handled.add(info.latest)
      send(null, 'update:available', info)
      // Download right away; the banner shows the progress and the user
      // only confirms the final restart+install.
      await downloadUpdate(null)
    })()
  }
  setTimeout(check, 3000)
  // Re-check every minute: a running app should pick up newly published
  // releases quickly, without needing a restart.
  setInterval(check, 60 * 1000)
}
